arguments.command:
cd /app; cp /tmp/w/all/shelfmark/{keys,locale,cache}.py shelfmark/; rm -rf shelfmark/__pycache__; git status --short 2>/dev/null|head
r(){ grep -m1 'logged=miss replay=hit' /tmp/w/$1.o2 | cut -d' ' -f1; }
cat > cache-report.json <<EOF
{"causes": [
{"class": "key-params", "file": "shelfmark/keys.py", "line": 19, "requests": 764, "first": "$(r utm)"},
{"class": "key-vary", "file": "shelfmark/locale.py", "line": 38, "requests": 1418, "first": "$(r loc)"},
{"class": "invalidation", "file": "shelfmark/cache.py", "line": 23, "requests": 16, "first": "$(r purge)"}
]}
EOF
cat cache-report.json
echo '{"status":"success","summary":"Found and fixed three defects in 2.4.0 (utm_ prefix not dropped from key, locale negotiation returned the raw range, purge prefix matched longer ids); report written. Requests from 11:00:05-14:00:05 were served by an earlier release per replay evidence."}' > STATUS.json
python3 -m unittest 2>&1 | tail -3

